"""Import fallback territory assets generated by NSS-pipeline.

The front-end keeps static GeoJSON files so maps render without a pipeline
service at runtime. Existing official IBGE neighborhoods always win; assets
from the pipeline are copied only when the front-end neighborhood file is
empty. This preserves the same precedence used by the analytics pipeline.
"""
from __future__ import annotations

import argparse
import json
import shutil
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "public" / "maps" / "national"


def write_json(path: Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", type=Path, required=True, help="Pipeline territory root, e.g. territories/rj-osm")
    args = parser.parse_args()
    source = args.source.resolve()
    if not source.is_dir():
        raise SystemExit(f"territory source does not exist: {source}")

    index_path = OUTPUT / "municipalities.index.json"
    index = json.loads(index_path.read_text(encoding="utf-8"))
    imported: list[str] = []
    for item in index.get("items", []):
        code = str(item["code"])
        source_path = source / code / "neighborhoods.geojson"
        target_path = OUTPUT / "neighborhoods" / f"{code}.geojson"
        if not source_path.exists():
            continue
        source_data = json.loads(source_path.read_text(encoding="utf-8"))
        if not source_data.get("features"):
            continue
        current_data = json.loads(target_path.read_text(encoding="utf-8")) if target_path.exists() else {}
        if current_data.get("features"):
            continue
        shutil.copyfile(source_path, target_path)
        item["neighborhoodsPath"] = f"neighborhoods/{code}.geojson"
        item["neighborhoodCount"] = len(source_data["features"])
        item["neighborhoodGeometryStatus"] = "AVAILABLE_OSM"
        item["neighborhoodSource"] = "OpenStreetMap"
        imported.append(code)

    write_json(index_path, index)
    manifest_path = OUTPUT / "manifest.json"
    manifest = json.loads(manifest_path.read_text(encoding="utf-8")) if manifest_path.exists() else {}
    fallback_sources = set(manifest.get("fallbackSources", []))
    if imported:
        fallback_sources.add("OpenStreetMap")
    manifest["fallbackSources"] = sorted(fallback_sources)
    manifest["neighborhoodFallbackCount"] = sum(
        1 for item in index.get("items", []) if item.get("neighborhoodGeometryStatus") == "AVAILABLE_OSM"
    )
    write_json(manifest_path, manifest)
    print(f"Imported {len(imported)} OpenStreetMap municipality assets: {', '.join(imported)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
